export function evaluate({inputs,time}){
const u=inputs.launchSpeed,g=inputs.gravity;
const T=u/g,H=u*u/(2*g);
const t=Math.min(Math.max(time,0),2*T);
const yt=u*t-g*t*t/2,vt=u-g*t;
const rel=t>=T-1e-9;
const tau=Math.max(0,t-T);
const yd=rel?H-g*tau*tau/2:H;
const vd=rel?-g*tau:0, ad=rel?-g:0;
const base=360,sc=250/2.2;
const Y=y=>base-y*sc;
const o=[];
const st1=t<1e-9?'At launch':Math.abs(t-T)<1e-6?'At the top':t<T?'Rising':(t>=2*T-1e-6?'At launch height':'Falling');
const st2=!rel?'Held in place':(Math.abs(t-T)<1e-6?'Just released':(t>=2*T-1e-6?'At launch height':'Falling together'));
o.push(...sdk.panel({id:'lane.toss',x:10,y:34,w:305,h:370,title:'Toss',state:st1}));
o.push(...sdk.panel({id:'lane.drop',x:325,y:34,w:305,h:370,title:'Drop',state:st2}));
const cx1=100,cx2=415;
o.push(...sdk.groundMark('mark.toss',cx1,base+14,80,'launch'));
o.push(...sdk.groundMark('mark.drop',cx2,base+14,80,'launch'));
o.push(...sdk.gate('gate.drop',cx2,Y(H)-18,{open:rel}));
if(rel){o.push(sdk.circle('ghost.drop',cx2,Y(H),24,{opacity:0.3}));}
o.push(sdk.circle('ball.toss',cx1,Y(yt),24,{}));
o.push(sdk.circle('ball.drop',cx2,Y(yd),24,{}));
const k=12;
o.push(...sdk.vector('vec.v.toss',{x:cx1-30,y:Y(yt)},{value:vt,direction:'up'},{scale:k,label:'v',role:'observed'}));
o.push(...sdk.vector('vec.a.toss',{x:cx1+30,y:Y(yt)},{value:-g,direction:'up'},{scale:k*0.6,label:'a',role:'warning'}));
o.push(...sdk.vector('vec.v.drop',{x:cx2-30,y:Y(yd)},{value:vd,direction:'up'},{scale:k,label:'v',role:'observed'}));
o.push(...sdk.vector('vec.a.drop',{x:cx2+30,y:Y(yd)},{value:ad,direction:'up'},{scale:k*0.6,label:'a',role:'warning'}));
o.push(...sdk.callout(cx1+45,Y(yt)-50,['v '+sdk.format(vt,2)+' m/s','a '+sdk.format(-g,1)+' m/s^2'],{id:'callout.toss'}));
o.push(...sdk.callout(cx2+45,Y(yd)-50,['v '+sdk.format(vd,2)+' m/s','a '+sdk.format(ad,1)+' m/s^2'],{id:'callout.drop'}));
return {frame:{width:640,height:420,objects:o,readouts:[{id:'tossedVelocity',value:vt},{id:'tossedAcceleration',value:-g},{id:'dropVelocity',value:vd},{id:'dropAcceleration',value:ad}]},quantities:{launchSpeed:u,gravity:g,apexTime:T,apexHeight:H,tossedVelocity:vt,tossedAcceleration:-g,tossedHeight:yt,dropVelocity:vd,dropAcceleration:ad,dropHeight:yd}};}
